package main

import "strings"

// sysprop_library: Soong's load hook (build/soong/sysprop/sysprop_library.go syspropLibraryHook) creates the cc library `lib<name>` (and java / rust
// modules, not built) next to the sysprop_library `<name>`, which is the java library's name. lookup falls back to synth (synth.go), which calls
// synthSysprop. The library's sources are the module's .sysprop srcs, generated by sysprop_cpp through the extension table (gensrc.go genSysprop).
//   - Properties: srcs, cpp.cflags; target.android: header_libs libbase_headers + shared_libs liblog; target.host: static_libs libbase, liblog.
//     host_supported (default false) is the host variant. Soong's mutated sysprop.platform (property_owner is "Platform") only chooses between the
//     internal and the public header dir an installed variant exports (cc/library.go): public for product-specific libraries and platform-owned
//     ones in the vendor image. This build is the platform variant, so genSysprop exports the internal dir for every library.
//   - Not built, one problem each: a sysprop_library that is soc / device / product specific (their variants export the public dir); the host
//     variant without host_supported.
//   - Dropped: cpp.ldflags (this build links with its own flags), cpp.min_sdk_version, the API check (sysprop_api_dump / sysprop_api_checker).

const syspropType = "sysprop_library"

// syspropBase: `lib<name>` -> name.
func syspropBase(ref string) (string, bool) {
	name, ok := strings.CutPrefix(strings.TrimPrefix(ref, ":"), "lib")
	return name, ok && name != ""
}

// syspropOwned: ref names the cc library of a sysprop_library the tree has.
func (g *Graph) syspropOwned(ref string) bool {
	name, ok := syspropBase(ref)
	return ok && (g.rawModule(name, Device, syspropType) != nil || g.rawModule(name, Host, syspropType) != nil)
}

// synthSysprop: the cc library `lib<name>` of the sysprop_library `<name>` (synth.go).
func (g *Graph) synthSysprop(ref string, side Side) *Module {
	name, ok := syspropBase(ref)
	if !ok {
		return nil
	}
	m := g.rawModule(name, side, syspropType)
	if m == nil {
		return nil
	}
	p := m.Props
	if len(p.strs("srcs")) == 0 {
		g.problem("%s: sysprop_library %s must specify srcs", ref, name)
		return nil
	}
	if side == Host && !p.boolean("host_supported", false) {
		g.problem("%s: sysprop_library %s has no host variant (host_supported unset)", ref, name)
		return nil
	}
	// cc/library.go: these select the public headers
	for _, specific := range []string{"soc_specific", "vendor", "proprietary", "device_specific", "odm", "product_specific"} {
		if p.boolean(specific, false) {
			g.problem("%s: sysprop_library %s is %s (only the platform variant is built)", ref, name, specific)
			return nil
		}
	}
	props := newObj()
	props.set("srcs", strVals(p.strs("srcs")))
	props.set("cflags", strVals(p.obj("cpp").strs("cflags")))
	android, host := newObj(), newObj()
	android.set("header_libs", strVals([]string{"libbase_headers"}))
	android.set("shared_libs", strVals([]string{"liblog"}))
	host.set("static_libs", strVals([]string{"libbase", "liblog"}))
	target := newObj()
	target.set("android", android)
	target.set("host", host)
	props.set("target", target)
	return &Module{Type: "cc_library", Name: ref, Dir: m.Dir, Props: props}
}
